n/// quote waits at most that long; every read counts against the shard\'s five a second.\n#[subscriber(KinesisStream::new("quotes").poll_interval(Duration::from_millis(200)))]\nasync fn reprice(quote: &Quote) -> HandlerOutcome {\n    tracing::info!(quote.symbol, quote.price, "repriced");\n    HandlerOutcome::ack()\n}\n\nfn service(broker: KinesisBroker) -> RustStream {\n    RustStream::new(AppInfo::new("pricing", "0.1.0")).with_broker(broker, |b| {\n        b.include(reprice);\n    })\n}\n'})})}),(0,n.jsx)(o.A,{value:"manual",label:"Manual",children:(0,n.jsx)(t.pre,{children:(0,n.jsx)(t.code,{className:"language-rust",metastring:'title="https://github.com/powersemmi/ruststream-kinesis/blob/main/crates/ruststream-kinesis/examples/manual/kinesis_subscriptions_poll.rs"',children:'/// Reprices on every quote. A quiet shard is read again 200 ms after an empty read, so a new\n/// quote waits at most that long; every read counts against the shard\'s five a second.\nstruct Reprice;\n\nimpl Handle<Quote> for Reprice {\n    fn handle(\n        &self,\n        quote: &Quote,\n        _outs: &(),\n        _ctx: &mut Context<\'_>,\n    ) -> impl Future<Output = Result<(), HandlerOutcome>> {\n        tracing::info!(quote.symbol, quote.price, "repriced");\n        ready(Ok(()))\n    }\n}\n\nfn service(broker: KinesisBroker) -> RustStream {\n    RustStream::new(AppInfo::new("pricing", "0.1.0")).with_broker(broker, |b| {\n        let quotes = KinesisStream::new("quotes").poll_interval(Duration::from_millis(200));\n        b.include(subscriber(quotes, Reprice).build());\n    })\n}\n'})})})]})]})}function h(e={}){let{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(p,{...e})}):p(e)}},7250(e,t,r){r.d(t,{A:()=>o});var s=r(4848);r(6540);var n=r(4164),a=r(7663);function i({children:e,className:t,hidden:r}){return(0,s.jsx)("div",{role:"tabpanel",className:(0,n.A)("tabItem_Ymn6",t),hidden:r,children:e})}function o({children:e,className:t,value:r}){let